-- candidate_countries_seed.sql
--
-- Full ISO 3166-1 country list for the registration form's country question
-- (T38). Generated from Node's ICU data, not hand-typed, so the names match
-- the CLDR English forms and nothing is missed.
--
-- Ordering: the 20 Latin American countries SDB staffs come first, then
-- everything else alphabetically. The field renders as a type-to-filter
-- combobox (SEARCHABLE_SELECT_MIN_OPTIONS in select-fields.tsx), so ordering
-- only affects the unfiltered list — search reaches any country immediately.
--
-- The stored VALUE is the full country name, not an alpha-2 code. This is not
-- cosmetic: `candidates.country` already holds full names everywhere else
-- (the dev-seed pool stores "Argentina", "Brazil", "Colombia"), and the
-- candidate filter matches on exact equality —
-- `and country = ${filters.country}` in candidates.repo.ts. Storing "MX" here
-- while the rest of the table says "Mexico" would silently split the same
-- country into two non-matching buckets.
--
-- Replaces any previously seeded options for this question. Deleting is safe
-- while nothing references them; `question_options` carries an
-- `on delete restrict` FK from the answer-option tables, so once a candidate
-- has answered, this DELETE will refuse rather than orphan an answer — which
-- is the guard rail described in 03-INTAKE-FORM-ENGINE §1.5 ("Options: change
-- value — blocked once referenced by any answer"). At that point add a new
-- option instead of rewriting this one.

delete from question_options where question_id = '00000000-0000-4000-8000-000000000521';

on conflict (id) do update
  set value = excluded.value,
      label = excluded.label,
      sort_order = excluded.sort_order;
